package io.knowledgebrain.planning;
import java.util.*;import java.time.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.postgresql.ds.PGSimpleDataSource;import org.flywaydb.core.Flyway;import org.springframework.jdbc.core.JdbcTemplate;import org.apache.kafka.clients.consumer.*;import io.knowledgebrain.contracts.planning.schedule.v1.*;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_PLANNING_KAFKA_BOOTSTRAP",matches=".+")
class ScheduleKafkaIntegrationTest {
 @Test void committedMovesZoneChangesRetainedTaskAndRetirementReachKafkaAsExactSnapshots()throws Exception{
  var ds=new PGSimpleDataSource();ds.setURL(System.getenv("BRAIN_TEST_PLANNING_DATABASE_URL"));ds.setUser("brain_planning");ds.setPassword(System.getenv("BRAIN_TEST_PLANNING_DATABASE_PASSWORD"));Flyway.configure().dataSource(ds).locations("classpath:db/migration").load().migrate();var store=new ScheduleStore(ds,Clock.systemUTC());var tasks=new TaskStore(ds,Clock.systemUTC());var ids=new UuidV7(Clock.systemUTC());var space=ids.next();var actor=ids.next();String trace="f".repeat(32),key=UUID.randomUUID().toString().replace("-","");var task=tasks.create(space,actor,key,new TaskStore.Input("Source Task","","NOT_STARTED",null,null),trace).task();var initial=new ScheduleStore.Input("Kafka Schedule","Original","2028-03-12T06:30:00Z","2028-03-12T07:30:00Z","America/New_York",task.taskId());var schedule=store.create(space,actor,key,initial,trace).schedule();store.create(space,actor,key,initial,trace);assertEquals(task,tasks.get(space,task.taskId()));tasks.change(space,task.taskId(),actor,1,null,true,trace);store.change(space,schedule.scheduleId(),actor,1,new ScheduleStore.Input("Moved","Edited","2028-11-05T05:30:00Z","2028-11-05T06:30:00Z","America/New_York",task.taskId()),false,trace);store.change(space,schedule.scheduleId(),actor,2,new ScheduleStore.Input("UTC label","Edited","2028-11-05T05:30:00Z","2028-11-05T06:30:00Z","UTC",null),false,trace);store.change(space,schedule.scheduleId(),actor,3,null,true,trace);
  var expected=new HashMap<String,byte[]>();new JdbcTemplate(ds).query("SELECT id,payload FROM outbox_event WHERE aggregateid=?",(rs,n)->Map.entry(rs.getObject(1,UUID.class).toString(),rs.getBytes(2)),schedule.scheduleId()).forEach(e->expected.put(e.getKey(),e.getValue()));assertEquals(4,expected.size());var p=new Properties();p.put("bootstrap.servers",System.getenv("BRAIN_TEST_PLANNING_KAFKA_BOOTSTRAP"));p.put("group.id","planning-validation-"+ids.next());p.put("enable.auto.commit","false");p.put("auto.offset.reset","earliest");p.put("key.deserializer","org.apache.kafka.common.serialization.StringDeserializer");p.put("value.deserializer","org.apache.kafka.common.serialization.ByteArrayDeserializer");p.put("security.protocol","SSL");p.put("ssl.endpoint.identification.algorithm","HTTPS");p.put("ssl.truststore.type","PEM");p.put("ssl.truststore.certificates",Files.readString(Path.of("/planning-kafka-test/ca.crt")));p.put("ssl.keystore.type","PEM");p.put("ssl.keystore.certificate.chain",Files.readString(Path.of("/planning-kafka-test/user.crt")));p.put("ssl.keystore.key",Files.readString(Path.of("/planning-kafka-test/user.key")));
  try(var c=new KafkaConsumer<String,byte[]>(p)){c.subscribe(List.of("planning.schedule.v1"));var found=new HashSet<String>();var versions=new ArrayList<Long>();long deadline=System.nanoTime()+Duration.ofSeconds(60).toNanos();while(found.size()<4&&System.nanoTime()<deadline)for(var row:c.poll(Duration.ofSeconds(1))){if(!schedule.scheduleId().toString().equals(row.key()))continue;var e=ScheduleEventEnvelopeV1.parseFrom(row.value());var v=ScheduleChangedPayloadV1.parseFrom(e.getPayload());assertArrayEquals(expected.get(e.getEventId()),row.value());assertEquals("planning-service",e.getProducer());assertEquals("Schedule",e.getAggregateType());assertEquals(space.toString(),e.getSpaceId());assertEquals(actor.toString(),e.getActorId());assertEquals(trace,e.getTraceId());assertEquals(1,e.getEventVersion());assertEquals(7,UUID.fromString(e.getEventId()).version());assertEquals(7,UUID.fromString(v.getRevisionId()).version());assertEquals(v.getVersion()==1?"ScheduleCreated":v.getVersion()==4?"ScheduleRetired":"ScheduleUpdated",e.getEventType());assertEquals("PRIVATE",v.getVisibility());assertEquals(v.getVersion()==4?"RETIRED":"ACTIVE",v.getState());assertEquals(v.getVersion()<=2?task.taskId().toString():"",v.getTaskId());assertEquals(v.getVersion()==1?"2028-03-12T06:30:00Z":"2028-11-05T05:30:00Z",v.getStartsAt());assertEquals(v.getVersion()==1?"-05:00":v.getVersion()==2?"-04:00":"Z",v.getStartsOffset());assertEquals(v.getVersion()==1?"-04:00":v.getVersion()==2?"-05:00":"Z",v.getEndsOffset());assertEquals(v.getVersion()<=2?"America/New_York":"UTC",v.getTimeZone());for(var pair:Map.of("id",e.getEventId(),"trace_id",trace,"schema_group","planning","schema_artifact","schedule-events","schema_version","1").entrySet()){assertNotNull(row.headers().lastHeader(pair.getKey()));assertEquals(pair.getValue(),new String(row.headers().lastHeader(pair.getKey()).value(),StandardCharsets.UTF_8));}if(found.add(e.getEventId()))versions.add(v.getVersion());}assertEquals(expected.keySet(),found);assertEquals(List.of(1L,2L,3L,4L),versions);}
 }
}
